import React, { useEffect, useState } from "react";
import { Container, Button, Modal, Form, Card } from "react-bootstrap";
import AdminNavbar from "./AdminNavbar";
import axios from "axios";

/* =========================
   IMÁGENES LOCALES
========================= */
import tambo from "../../assets/images/tambo_perro.jpg";
import luna from "../../assets/images/luna_gato.jpg";
import toby from "../../assets/images/toby_perro.jpg";
import frida from "../../assets/images/frida_perro.jpg";
import michi from "../../assets/images/michi_techo.jpg";
import rocky from "../../assets/images/rocky_cachorro.jpg";

/* =========================
   MAPA DE IMÁGENES
========================= */
const imageMap = {
  "tambo_perro.jpg": tambo,
  "luna_gato.jpg": luna,
  "toby_perro.jpg": toby,
  "frida_perro.jpg": frida,
  "michi_techo.jpg": michi,
  "rocky_cachorro.jpg": rocky,
};

function Animals() {
  const [animals, setAnimals] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);

  const [formData, setFormData] = useState({
    nombre: "",
    especie: "Perro",
    descripcion: "",
    fotos: "",
    estado: "disponible",
  });

  const [editData, setEditData] = useState({
    id_animal: null,
    estado: "",
  });

  const token = localStorage.getItem("token");

  /* =========================
     CONSULTAR ANIMALES
  ========================= */
  const fetchAnimals = async () => {
    const res = await axios.get("http://localhost:5000/animals/", {
      headers: { Authorization: `Bearer ${token}` },
    });
    setAnimals(res.data);
  };

  useEffect(() => {
    fetchAnimals();
  }, []);

  /* =========================
     CREAR
  ========================= */
  const handleSave = async () => {
    await axios.post(
      "http://localhost:5000/animals/createAnimal",
      formData,
      { headers: { Authorization: `Bearer ${token}` } }
    );
    setShowModal(false);
    fetchAnimals();
  };

  /* =========================
     EDITAR
  ========================= */
  const handleEditSave = async () => {
    await axios.put(
      `http://localhost:5000/animals/updateAnimal/${editData.id_animal}`,
      { estado: editData.estado },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    setShowEditModal(false);
    fetchAnimals();
  };

  /* =========================
     ELIMINAR
  ========================= */
  const handleDelete = async (animal) => {
    if (animal.estado === "disponible") {
      alert("No se puede eliminar un animal disponible");
      return;
    }

    if (window.confirm(`¿Eliminar a ${animal.nombre}?`)) {
      await axios.delete(
        `http://localhost:5000/animals/deleteAnimal/${animal.id_animal}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchAnimals();
    }
  };

  return (
    <>
      <AdminNavbar />
      <Container className="mt-4">
        <div className="d-flex justify-content-between mb-4">
          <h1 style={{ color: "#2364c7", fontWeight: "bold" }}>
            Panel de Animales
          </h1>

          <div>
            <Button
              variant="primary"
              className="me-2"
              onClick={fetchAnimals}
            >
              Consultar
            </Button>
            <Button variant="success" onClick={() => setShowModal(true)}>
              Agregar
            </Button>
          </div>
        </div>

        {/* =========================
            GRID TIPO PINTEREST
        ========================= */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: "20px",
          }}
        >
          {animals.map((animal) => (
            <Card
              key={animal.id_animal}
              style={{
                borderRadius: "16px",
                overflow: "hidden",
                boxShadow: "0 6px 18px rgba(0,0,0,0.15)",
              }}
            >
              <Card.Img
                variant="top"
                src={imageMap[animal.fotos]}
                style={{ height: "260px", objectFit: "cover" }}
              />
              <Card.Body>
                <Card.Title>{animal.nombre}</Card.Title>
                <Card.Subtitle className="mb-2 text-muted">
                  {animal.especie}
                </Card.Subtitle>
                <Card.Text>{animal.descripcion}</Card.Text>
                <strong>Estado:</strong> {animal.estado}

                <div className="d-flex justify-content-between mt-3">
                  <Button
                    size="sm"
                    variant="info"
                    onClick={() => {
                      setEditData({
                        id_animal: animal.id_animal,
                        estado: animal.estado,
                      });
                      setShowEditModal(true);
                    }}
                  >
                    Editar
                  </Button>

                  <Button
                    size="sm"
                    variant="danger"
                    onClick={() => handleDelete(animal)}
                  >
                    Eliminar
                  </Button>
                </div>
              </Card.Body>
            </Card>
          ))}
        </div>

        {/* =========================
            MODAL CREAR
        ========================= */}
        <Modal show={showModal} onHide={() => setShowModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Agregar Animal</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Control
              className="mb-2"
              placeholder="Nombre"
              onChange={(e) =>
                setFormData({ ...formData, nombre: e.target.value })
              }
            />
            <Form.Select
              className="mb-2"
              onChange={(e) =>
                setFormData({ ...formData, especie: e.target.value })
              }
            >
              <option>Perro</option>
              <option>Gato</option>
            </Form.Select>
            <Form.Control
              as="textarea"
              rows={3}
              className="mb-2"
              placeholder="Descripción"
              onChange={(e) =>
                setFormData({ ...formData, descripcion: e.target.value })
              }
            />
            <Form.Control
              placeholder="Imagen (ej: tambo_perro.jpg)"
              onChange={(e) =>
                setFormData({ ...formData, fotos: e.target.value })
              }
            />
          </Modal.Body>
          <Modal.Footer>
            <Button onClick={handleSave}>Guardar</Button>
          </Modal.Footer>
        </Modal>

        {/* =========================
            MODAL EDITAR
        ========================= */}
        <Modal show={showEditModal} onHide={() => setShowEditModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Editar Estado</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Select
              value={editData.estado}
              onChange={(e) =>
                setEditData({ ...editData, estado: e.target.value })
              }
            >
              <option value="disponible">Disponible</option>
              <option value="adoptado">Adoptado</option>
              <option value="en_tratamiento">En tratamiento</option>
            </Form.Select>
          </Modal.Body>
          <Modal.Footer>
            <Button onClick={handleEditSave}>Guardar</Button>
          </Modal.Footer>
        </Modal>
      </Container>
    </>
  );
}

export default Animals;
